não de gestão geral de recrutamento.","certainty":"adjudicated_medium"},{"uri":"http://data.europa.eu/esco/skill/ca0c9312-5ff2-4311-97c8-2fa614616acd","category":"S2","reason":"O foco é reter e recuperar instruções para uso posterior, isto é, gerir pessoalmente informação e memória, não executar a montagem.","certainty":"adjudicated_high"},{"uri":"http://data.europa.eu/esco/skill/ca0f9294-09f6-4528-bb3d-604955f8acfd","category":"H4","reason":"Envolve adquirir, armazenar e controlar abastecimentos e equipamentos agrícolas.","certainty":"high"},{"uri":"http://data.europa.eu/esco/skill/ca17f0df-59e4-4ed2-9360-fc5325bc7151","category":"H2","reason":"O objeto principal é operar, monitorizar e efetuar intervenções básicas em equipamentos técnicos.","certainty":"high"},{"uri":"http://data.europa.eu/esco/skill/ca180ac5-3b49-438e-992b-57f2af49c1e3","category":"H1","reason":"O aconselhamento é especializado em medicamentos, utilização, reações adversas e interações farmacêuticas.","certainty":"high"},{"uri":"http://data.europa.eu/esco/skill/ca1844f3-933d-468f-9c2a-ae67c618ce88","category":"H3","reason":"Rever questionários quanto à exatidão e adequação ao objetivo é uma prática metodológica de controlo e avaliação de instrumentos de recolha de dados.","certainty":"adjudicated_medium"},{"uri":"http://data.europa.eu/esco/skill/ca192ad9-39d9-49aa-8e87-b174906470b3","category":"H2","reason":"Refere-se ao uso de equipamento específico para polimento e lixagem de metais.","certainty":"high"},{"uri":"http://data.europa.eu/esco/skill/ca1a708c-0178-4ef3-8b5a-1eabfc533b0a","category":"H3","reason":"Consiste em aplicar técnicas e produtos de manutenção de revestimentos e proteção anticorrosiva de condutas.","certainty":"high"},{"uri":"http://data.europa.eu/esco/skill/ca1e4742-42cc-463a-9b12-a1733f06d7a3","category":"H3","reason":"Envolve o procedimento técnico de abrir canais em paredes, encaminhar cabos e realizar o respetivo acabamento.","certainty":"high"},{"uri":"http://data.europa.eu/esco/skill/ca1ec813-89b7-4c37-b465-1a70d0fba177","category":"H2","reason":"O foco é vigiar e controlar equipamento concreto de transferência de cimento, como bombas e transportadores.","certainty":"high"},{"uri":"http://data.europa.eu/esco/skill/ca226595-beda-406b-a0ac-c65c40784ca4","category":"H4","reason":"Envolve controlo estruturado de faturação e cobranças em operações de transporte de mercadorias.","certainty":"high"},{"uri":"http://data.europa.eu/esco/skill/ca273412-56a5-487e-a58b-2539abc0d730","category":"H3","reason":"Consiste na técnica estruturada de esboçar e desenhar estudos preparatórios para escultura.","certainty":"medium"},{"uri":"http://data.europa.eu/esco/skill/ca2a7a85-43cf-43c0-b703-f18fed7dfba5","category":"H1","reason":"Trata-se de conhecimento especializado sobre impactos da aquicultura e captura em recursos aquáticos.","certainty":"high"},{"uri":"http://data.europa.eu/esco/skill/ca309d1f-e080-42a3-b828-1c16e74aa9e7","category":"H3","reason":"Refere-se à técnica de aplicar e acabar argamassa em juntas de alvenaria.","certainty":"high"},{"uri":"http://data.europa.eu/esco/skill/ca326dd0-324f-43fe-81c5-4b40ddb35223","category":"H1","reason":"Trata-se de conhecimento especializado sobre indicadores de recursos, realizações e resultados em fundos da UE.","certainty":"high"},{"uri":"http://data.europa.eu/esco/skill/ca38245a-4ae3-42d0-b00b-c63b73c361dc","category":"H4","reason":"Envolve executar e controlar cobranças de taxas de licença em conformidade com procedimentos e regulamentação.","certainty":"high"},{"uri":"http://data.europa.eu/esco/skill/ca3a023b-e604-4133-a620-3a587183d2c5","category":"H3","reason":"Consiste no procedimento técnico de instalar materiais isolantes para proteção de estradas contra geada.","certainty":"high"},{"uri":"http://data.europa.eu/esco/skill/ca3ee513-2285-42c0-9b2a-287d65b5f7a2","category":"H3","reason":"Refere-se à técnica manual de nivelar e alisar betão recém-vertido.","certainty":"high"},{"uri":"http://data.europa.eu/esco/skill/ca484f72-3ae0-4670-97d8-5aa2d456155a","category":"H3","reason":"Refere-se a processos químicos estruturados para remover gases ácidos de correntes de gás.","certainty":"high"},{"uri":"http://data.europa.eu/esco/skill/ca49669b-1f59-4d1a-8e77-c77014ba93dc","category":"H3","reason":"Consiste na técnica operacional de introduzir texto rapidamente por teclado.","certainty":"high"},{"uri":"http://data.europa.eu/esco/skill/ca49f512-4434-49c1-8f49-9a078b60d2fe","category":"H3","reason":"Envolve a execução de procedimentos estabelecidos de resposta e evacuação em emergências.","certainty":"high"}]$m82_json$::jsonb;
  v_found integer;
begin
  select count(distinct item.uri) into v_found
  from jsonb_to_recordset(v_input) as item(uri text, category text, reason text, certainty text)
  join public.knowledge_external_mappings mapping on mapping.external_uri = item.uri
  join public.knowledge_sources source on source.id = mapping.source_id and source.name = 'ESCO'
  join public.knowledge_source_versions source_version on source_version.id = mapping.source_version_id
    and source_version.external_version = '1.2.1' and source_version.import_status = 'published'
  join public.knowledge_concepts concept on concept.id = mapping.concept_id
    and concept.scope = 'global' and concept.status = 'approved'
    and concept.concept_type not in ('occupation','certification');
  if v_found <> jsonb_array_length(v_input) then
    raise exception 'M82_ESCO_MAPPING_MISMATCH: found %, expected %', v_found, jsonb_array_length(v_input);
  end if;
  if exists (
    select mapping.concept_id
    from jsonb_to_recordset(v_input) as item(uri text, category text, reason text, certainty text)
    join public.knowledge_external_mappings mapping on mapping.external_uri = item.uri
    join public.knowledge_sources source on source.id = mapping.source_id and source.name = 'ESCO'
    group by mapping.concept_id having count(distinct item.category)>1
  ) then raise exception 'M82_ESCO_CANONICAL_CLASS_CONFLICT'; end if;
  insert into public.knowledge_competency_classifications
    (concept_id, subgroup_id, version, taxonomy_version, method, provenance)
  select distinct on (concept.id)
    concept.id, subgroup.id,
    coalesce((select max(history.version)+1 from public.knowledge_competency_classifications history
      where history.concept_id=concept.id),1),
    'competency-taxonomy-2.0.0', 'ai_assisted',
    jsonb_build_object('source','ESCO','sourceVersion','1.2.1','sourceURI',item.uri,
      'sourceHash','1b5e5356d4037cdd5c938131b385b9059a1e5f256ca621e8372b6633ec9aea80',
      'classifierVersion','prisma-competency-classification-1.1.0',
      'model','gpt-5.6-terra', 'reason',item.reason,'certainty',item.certainty,
      'agreement','M8.2-1.0.0')
  from jsonb_to_recordset(v_input) as item(uri text, category text, reason text, certainty text)
  join public.knowledge_external_mappings mapping on mapping.external_uri = item.uri
  join public.knowledge_sources source on source.id = mapping.source_id and source.name = 'ESCO'
  join public.knowledge_source_versions source_version on source_version.id = mapping.source_version_id
    and source_version.external_version = '1.2.1' and source_version.import_status = 'published'
  join public.knowledge_concepts concept on concept.id = mapping.concept_id
    and concept.scope = 'global' and concept.status = 'approved'
    and concept.concept_type not in ('occupation','certification')
  join public.competency_subgroups subgroup on subgroup.code=item.category and subgroup.scope='global' and subgroup.status='active'
  where not exists (select 1 from public.knowledge_competency_classifications current_class
    where current_class.concept_id=concept.id and current_class.is_current)
  order by concept.id,item.uri;
end $m82$;
